// Node "Preparar dados" do workflow Feedback.
// Monta o prompt_feedback na versao validada 2026-06-novo-questionario.
//
// As frases abaixo sao as mesmas do MAP da ferramenta paliativa
// (g-calixto/sti-prompt-tester, src/App.jsx). Qualquer mudanca aqui tem de
// ser espelhada la, senao os prompts dos dois ambientes divergem e os dados
// da pesquisa deixam de ser comparaveis.
//
// O calculo correto/incorreto NAO acontece aqui: vem pronto do backend
// (evaluationService.js). Duplicar esse calculo aqui foi o bug original.

const input = $input.first().json;
const body = input.body ?? input;
const extracao = body.extracao ?? {};
const avaliacao = body.avaliacao ?? {};
const questionario = body.questionario ?? {};
const contexto = questionario.contexto_pedagogico ?? {};
const perfil = questionario.perfil_emocional ?? {};
const casoCorreto = questionario.caso_correto ?? {};
const casoIncorreto = questionario.caso_incorreto ?? {};
const regeneracao = body.regeneracao ?? {};

const submission_id = String(body.submission_id ?? "").trim();
const correct_answer = String(body.correct_answer ?? "").trim();
const feedback_generation = Number(body.feedback_generation ?? 1);

const enunciado = String(extracao.enunciado ?? "").trim();
const desenvolvimento_aluno = String(extracao.desenvolvimento_aluno ?? "").trim();
const resposta_aluno = String(extracao.resposta_aluno ?? "").trim();
const legibilidade = String(extracao.legibilidade ?? "").trim();
const confianca_extracao = Number(extracao.confianca_extracao ?? 0);
const observacoes_extracao = String(extracao.observacoes ?? "").trim();

const status_avaliacao_oficial = String(avaliacao.status ?? "").trim();
const resposta_correta = Boolean(avaliacao.resposta_correta);
const correta = status_avaliacao_oficial === "correta";
const tipo_prompt = correta ? "resposta_correta" : "resposta_incorreta";

const intencao_professor = String(body.intencao_professor ?? "").trim();
const regeneracao_solicitada = Boolean(regeneracao.solicitada);
const regeneracao_instrucao = String(regeneracao.instrucao ?? "").trim();

const questionario_tipo = String(questionario.tipo ?? "").trim();
const momento_conteudo = String(contexto.momento_conteudo ?? "").trim();
const profundidade_conteudo = String(contexto.profundidade_conteudo ?? "").trim();
// estrategia_usada passou a ser escolha unica (CP3 da ferramenta). O array
// antigo continua sendo aceito para nao quebrar chamadas de versoes anteriores.
const estrategia_usada = String(
  contexto.estrategia_usada ??
    (Array.isArray(contexto.estrategias_usadas) ? contexto.estrategias_usadas[0] : "") ??
    ""
).trim();
const reacao_ao_erro = String(perfil.reacao_ao_erro ?? "").trim();
const relacao_com_matematica = String(perfil.relacao_com_matematica ?? "").trim();
const receptividade_feedback = String(perfil.receptividade_feedback ?? "").trim();
const acerto_esperado = String(casoCorreto.acerto_esperado ?? "").trim();
const desempenho_geral = String(casoIncorreto.desempenho_geral ?? "").trim();
const frequencia_erro = String(casoIncorreto.frequencia_erro ?? "").trim();
const natureza_erro = String(casoIncorreto.natureza_erro ?? "").trim();

// ---------------------------------------------------------------------------
// Questionario: slug -> trecho de frase que entra no buraco do prompt.
// As frases sao as mesmas do MAP da ferramenta paliativa, na mesma ordem.
// ---------------------------------------------------------------------------
const QUESTIONARIO = {
  // CP1) "Este conteúdo foi trabalhado {{...}}."
  momento_conteudo: {
    nesta_semana: "nesta semana",
    duas_a_quatro_semanas: "de 2 a 4 semanas atrás",
    neste_semestre: "neste semestre, há mais de um mês",
    semestres_anteriores: "em semestres anteriores"
  },
  // CP2) "Em relação à profundidade, {{...}}."
  profundidade_conteudo: {
    em_profundidade: "foi trabalhado em profundidade, com prática extensiva e aplicação em diferentes contextos",
    bem_trabalhado: "foi bem trabalhado, com prática relevante",
    superficial: "foi trabalhado de forma superficial, com pouca prática",
    apenas_teorico: "foi apenas apresentado teoricamente, sem prática associada"
  },
  // CP3) "Em aula, foi trabalhado por meio de {{...}}."
  estrategia_usada: {
    explicacao_direta: "exposição direta com explicação/lousa",
    resolucao_em_grupo: "resolução de problemas em grupo",
    resolucao_individual: "resolução de problemas individualmente",
    atividade_pratica: "atividade prática/experimental"
  },
  // DSP1 incorreta) "Desempenho geral em matemática:\n{{...}}"
  desempenho_geral: {
    abaixo_da_media: "Abaixo da média",
    na_media: "Na média",
    acima_da_media: "Acima da média"
  },
  // DSP2) "Este tipo de erro {{...}}."
  frequencia_erro: {
    primeira_vez: "apareceu pela primeira vez",
    as_vezes: "acontece às vezes ou algumas vezes",
    quase_sempre: "acontece quase sempre"
  },
  // DSP3) "O erro parece ser de {{...}}."
  natureza_erro: {
    compreensao_conceito: "compreensão do conceito",
    distracao: "distração",
    interpretacao_enunciado: "interpretação do enunciado",
    calculo_execucao: "cálculo/execução"
  },
  // DSP1 correta) "O acerto {{...}}."
  acerto_esperado: {
    sim_esperado: "era esperado",
    sim_com_dificuldade_usual: "era esperado, mas o aluno costuma ter dificuldade nesse conteúdo",
    nao_surpresa_positiva: "foi uma surpresa positiva"
  },
  // PEE1) "esse aluno {{...}} quando erra"
  reacao_ao_erro: {
    frustracao: "fica frustrado",
    indiferenca: "fica indiferente",
    busca_compreender: "quer entender o erro",
    ansiedade: "fica ansioso",
    variavel: "varia muito"
  },
  // PEE2) "{{...}} em relação à matemática"
  // A ferramenta troca a ordem das palavras da ultima opcao conforme o caso.
  relacao_com_matematica: {
    confianca: "demonstra confiança",
    interesse: "demonstra interesse",
    desinteresse: "demonstra desinteresse",
    resistencia: "demonstra resistência",
    ansiedade_bloqueio: correta ? "demonstra bloqueio ou ansiedade" : "demonstra ansiedade ou bloqueio"
  },
  // PEE3) "{{...}} ao feedback"
  receptividade_feedback: {
    boa: "recebe bem",
    depende_da_abordagem: "depende de como é dado",
    tende_a_resistir: "tende a resistir"
  }
};

function conhecido(campo, valor) {
  return Boolean(QUESTIONARIO[campo] && QUESTIONARIO[campo][valor]);
}

function frase(campo, valor) {
  return conhecido(campo, valor) ? QUESTIONARIO[campo][valor] : "";
}

// ---------------------------------------------------------------------------
// Montagem do prompt (mesma estrutura de buildPromptFinal da ferramenta)
// ---------------------------------------------------------------------------

const comeco = correta
  ? "Crie um feedback em linguagem acessível, acolhedora e adequada para crianças dos anos iniciais do Ensino Fundamental.\n\nO aluno acertou a resposta. Sua tarefa é produzir um feedback que valorize o acerto, reconheça o progresso e ajude o aluno a continuar avançando, sem apenas parabenizar de forma genérica."
  : "Crie um feedback em linguagem acessível, acolhedora e adequada para crianças dos anos iniciais do Ensino Fundamental.\n\nO aluno não chegou à resposta correta. Sua tarefa é produzir um feedback que reconheça o esforço, oriente passo a passo, sem constranger, punir ou entregar diretamente a resposta correta e encoraje o aluno, provocando uma reflexão sobre o erro.";

const dados_questao =
  "## Dados da questão\n\n" +
  "Enunciado da questão:\n" + enunciado + "\n\n" +
  "Desenvolvimento do aluno:\n" + desenvolvimento_aluno + "\n\n" +
  "Resposta final do aluno:\n" + resposta_aluno + "\n\n" +
  "Resposta correta esperada:\n" + correct_answer + "\n\n" +
  "Observação importante: a resposta correta esperada é uma informação interna para orientar sua análise. Não revele explicitamente a resposta correta no feedback.";

const obs_texto = intencao_professor || "Não informado.";

const linha_conteudo =
  "Este conteúdo foi trabalhado " + frase("momento_conteudo", momento_conteudo) +
  ". Em relação à profundidade, " + frase("profundidade_conteudo", profundidade_conteudo) +
  ". Em aula, foi trabalhado por meio de " + frase("estrategia_usada", estrategia_usada) + ".";

const linha_perfil =
  "Perfil emocional: esse aluno " + frase("reacao_ao_erro", reacao_ao_erro) +
  " quando erra; " + frase("relacao_com_matematica", relacao_com_matematica) +
  " em relação à matemática; e " + frase("receptividade_feedback", receptividade_feedback) + " ao feedback.";

const linha_intencao = "Informação adicional do professor, se houver:\n" + obs_texto;

const contexto_aluno = correta
  ? linha_conteudo + "\n\n" +
    "O acerto " + frase("acerto_esperado", acerto_esperado) + ".\n\n" +
    linha_perfil + "\n\n" +
    linha_intencao
  : linha_conteudo + "\n\n" +
    "Desempenho geral em matemática:\n" + frase("desempenho_geral", desempenho_geral) + "\n\n" +
    "Este tipo de erro " + frase("frequencia_erro", frequencia_erro) + ".\n\n" +
    "O erro parece ser de " + frase("natureza_erro", natureza_erro) + ".\n\n" +
    linha_perfil + "\n\n" +
    linha_intencao;

const estrutura_regras = correta
  ? "## Estrutura obrigatória do feedback\n\nO feedback deve seguir esta estrutura:\n\n1. Reconhecimento inicial do acerto.\n2. Menção específica ao que o aluno demonstrou compreender ou fazer bem.\n3. Reconhecimento do esforço, aprofundamento do conceito, generalização para novos contextos e um pequeno desafio para continuar avançando.\n\n## Regras de escrita\n\n* Use linguagem simples, respeitosa e encorajadora.\n* Escreva diretamente para o aluno.\n* Não use tom excessivamente infantilizado.\n* Não invente informações sobre o aluno, a turma ou a aula.\n* Use apenas os dados fornecidos.\n* Adapte o tom ao perfil emocional informado pelo professor.\n* Não revele explicitamente a resposta correta.\n* Não diga apenas \"parabéns\"; explique o motivo do acerto.\n* O feedback deve ter no máximo 10 linhas.\n* Não use markdown no texto do feedback.\n* Não use listas numeradas no texto do feedback.\n\n## Formato de saída obrigatório\n\nRetorne apenas um JSON válido, sem markdown, no seguinte formato:\n\n{\n  \"feedback_aluno\": \"\"\n}\n\nNo campo \"feedback_aluno\", escreva o feedback direcionado ao aluno."
  : "## Estrutura obrigatória do feedback\n\nO feedback deve seguir esta estrutura:\n\n1. Reconhecimento inicial do esforço ou da tentativa do aluno.\n2. Orientação passo a passo sobre onde o raciocínio pode ter se desviado.\n3. Encorajamento, provocação de reflexão sobre o erro e orientação clara para o próximo passo.\n\n## Regras de escrita\n\n* Use linguagem simples, respeitosa e encorajadora.\n* Escreva diretamente para o aluno.\n* Não use tom excessivamente infantilizado.\n* Não invente informações sobre o aluno, a turma ou a aula.\n* Use apenas os dados fornecidos.\n* Trate o tipo de erro como uma hipótese pedagógica, não como uma certeza absoluta.\n* Adapte o tom ao perfil emocional informado pelo professor.\n* Não revele explicitamente a resposta correta.\n* Não resolva toda a questão pelo aluno.\n* Não use frases como \"você errou feio\", \"você não entendeu\" ou qualquer formulação punitiva.\n* Ajude o aluno a revisar o caminho, perceber o ponto de atenção e tentar novamente.\n* O feedback deve ter no máximo 10 linhas.\n* Não use markdown no texto do feedback.\n* Não use listas numeradas no texto do feedback.\n\n## Formato de saída obrigatório\n\nRetorne apenas um JSON válido, sem markdown, no seguinte formato:\n\n{\n  \"feedback_aluno\": \"\"\n}\n\nNo campo \"feedback_aluno\", escreva o feedback direcionado ao aluno.";

const prompt_base =
  comeco + "\n\n" + dados_questao + "\n\n## Contexto do aluno\n\n" + contexto_aluno + "\n\n" + estrutura_regras;

const bloco_regeneracao = regeneracao_solicitada
  ? "\n\n\n## Nova versão solicitada pelo professor\n\n" +
    "Esta é uma regeração de um feedback já gerado antes. O professor pediu os seguintes ajustes:\n\n" +
    "\"" + (regeneracao_instrucao || "sem instrução específica, apenas gerar uma nova variação") + "\"\n\n" +
    "Gere uma nova versão do feedback seguindo essa instrução e mantendo todas as regras acima."
  : "";

const prompt_feedback = prompt_base + bloco_regeneracao;

// Uma resposta que nao casa com nenhuma opcao vira "_" no codigo. Se sobrar
// algum "_" dentro dos blocos, o questionario chegou incompleto ou com slug
// desconhecido, e o prompt sairia com buracos.
const respostas_obrigatorias = correta
  ? [
      ["momento_conteudo", momento_conteudo],
      ["profundidade_conteudo", profundidade_conteudo],
      ["estrategia_usada", estrategia_usada],
      ["acerto_esperado", acerto_esperado],
      ["reacao_ao_erro", reacao_ao_erro],
      ["relacao_com_matematica", relacao_com_matematica],
      ["receptividade_feedback", receptividade_feedback]
    ]
  : [
      ["momento_conteudo", momento_conteudo],
      ["profundidade_conteudo", profundidade_conteudo],
      ["estrategia_usada", estrategia_usada],
      ["desempenho_geral", desempenho_geral],
      ["frequencia_erro", frequencia_erro],
      ["natureza_erro", natureza_erro],
      ["reacao_ao_erro", reacao_ao_erro],
      ["relacao_com_matematica", relacao_com_matematica],
      ["receptividade_feedback", receptividade_feedback]
    ];

const respostas_faltando = respostas_obrigatorias
  .filter(([campo, valor]) => !conhecido(campo, valor))
  .map(([campo]) => campo);

const entrada_valida = Boolean(
  submission_id &&
  correct_answer &&
  enunciado &&
  resposta_aluno &&
  status_avaliacao_oficial &&
  respostas_faltando.length === 0
);

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      submission_id,
      feedback_generation,
      correct_answer,
      enunciado,
      desenvolvimento_aluno,
      resposta_aluno,
      legibilidade,
      confianca_extracao,
      observacoes_extracao,
      status_avaliacao_oficial,
      resposta_correta,
      tipo_prompt,
      versao_prompt: "2026-06-novo-questionario",
      questionario_tipo,
      momento_conteudo,
      profundidade_conteudo,
      estrategia_usada,
      // A planilha da pesquisa tem uma coluna chamada "estrategias_usadas",
      // do tempo em que CP3 era multipla escolha. Mantemos o campo com o nome
      // antigo para a coluna continuar sendo preenchida sem mexer na planilha.
      estrategias_usadas: estrategia_usada,
      reacao_ao_erro,
      relacao_com_matematica,
      receptividade_feedback,
      acerto_esperado,
      desempenho_geral,
      frequencia_erro,
      natureza_erro,
      intencao_professor,
      regeneracao_solicitada,
      regeneracao_instrucao,
      entrada_valida,
      respostas_faltando: respostas_faltando.join(", "),
      prompt_feedback,
      provedor_ia: "gemini",
      modelo_feedback: "gemini"
    }
  }
];

const original = $('Preparar dados').first().json;
const aiOutput = $input.first().json;

function getText(value) {
  if (!value) return "";

  if (typeof value === "string") {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map(getText).filter(Boolean).join("\n");
  }

  if (typeof value === "object") {
    const priorityKeys = [
      "text",
      "output",
      "response",
      "content",
      "message",
      "result"
    ];

    for (const key of priorityKeys) {
      if (value[key]) {
        const found = getText(value[key]);
        if (found) return found;
      }
    }

    if (value.candidates?.[0]?.content?.parts) {
      return getText(value.candidates[0].content.parts);
    }

    if (value.content?.parts) {
      return getText(value.content.parts);
    }
  }

  return "";
}

function extractJson(raw) {
  if (!raw) return null;

  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1 || end <= start) {
    return null;
  }

  const jsonText = cleaned.slice(start, end + 1);

  try {
    return JSON.parse(jsonText);
  } catch (error) {
    return null;
  }
}

const raw_ai_response = getText(aiOutput);
const feedback = extractJson(raw_ai_response);

const parse_ok = feedback !== null;

const feedback_aluno = feedback?.feedback_aluno ?? "";

// Unico campo realmente exigido pelo backend. Antes exigia tambem
// feedback_professor, que os prompts atuais nunca retornam - isso fazia
// "ok" ser sempre falso mesmo em geracoes bem-sucedidas.
const ok = parse_ok && Boolean(feedback_aluno);

// Campos legado: usam o que a IA retornar; se ausentes, ficam null em vez
// de texto fabricado (o frontend novo nao exibe esses campos mesmo).
const acertou =
  typeof feedback?.acertou === "boolean" ? feedback.acertou : original.resposta_correta;

const status_avaliacao = feedback?.status_avaliacao ?? original.status_avaliacao_oficial ?? null;
const tipo_erro = feedback?.tipo_erro ?? null;
const resumo_erro = feedback?.resumo_erro ?? null;
const feedback_professor = feedback?.feedback_professor ?? null;
const dica_proxima_acao = feedback?.dica_proxima_acao ?? null;
const confianca_feedback =
  feedback?.confianca_feedback !== undefined ? Number(feedback.confianca_feedback) : null;

const status_n8n = ok ? "feedback_gerado_com_sucesso" : "erro_feedback_ia";

const resposta_backend = {
  ok,
  submission_id: original.submission_id,
  fluxo: "geracao_feedback",
  status_n8n,
  feedback_generation: original.feedback_generation,
  provedor_ia: original.provedor_ia,
  modelo: original.modelo_feedback,
  avaliacao: {
    feedback_aluno,
    acertou,
    status_avaliacao,
    tipo_erro,
    resumo_erro,
    feedback_professor,
    dica_proxima_acao,
    confianca_feedback
  },
  entrada: {
    correct_answer: original.correct_answer,
    enunciado: original.enunciado,
    desenvolvimento_aluno: original.desenvolvimento_aluno,
    resposta_aluno: original.resposta_aluno,
    legibilidade: original.legibilidade,
    confianca_extracao: original.confianca_extracao,
    observacoes_extracao: original.observacoes_extracao
  },
  erro: ok
    ? null
    : {
        parse_ok,
        mensagem: parse_ok
          ? "A IA nao retornou feedback_aluno."
          : "A resposta da IA nao contem JSON valido."
      }
};

return [
  {
    json: {
      ...original,
      parse_ok,
      ok,
      status_n8n,
      modelo: original.modelo_feedback,
      acertou,
      status_avaliacao,
      tipo_erro,
      resumo_erro,
      feedback_aluno,
      feedback_professor,
      dica_proxima_acao,
      confianca_feedback,
      raw_ai_response,
      resposta_backend_json: JSON.stringify(resposta_backend),
      resposta_backend
    }
  }
];
